SQL_STMT_U.val:
SELECT pf.supplier_id, s.name, pf.year_month, pf.slip_count, pf.payment_slip_count, pf.previous_balance, pf.standard_purchase_amount, pf.standard_return_amount, pf.standard_discount_amount, pf.standard_taxamount, pf.reduced_purchase_amount, pf.reduced_return_amount, pf.reduced_discount_amount, pf.reduced_tax_amount, pf.tax_adjustment, pf.payment_amount, pf.current_balance,
SUM(COALESCE(pf.previous_balance,0)) OVER () AS total_previous_balance, SUM( COALESCE(pf.reduced_purchase_amount,0) + COALESCE(pf.standard_purchase_amount,0) ) OVER () AS total_sales, SUM( COALESCE(pf.reduced_return_amount,0) + COALESCE(pf.standard_return_amount,0) ) OVER () AS total_returns, SUM( COALESCE(pf.reduced_discount_amount,0) + COALESCE(pf.standard_discount_amount,0) ) OVER () AS total_discounts, SUM( CASE WHEN s.tax_category = 2 THEN 0 ELSE COALESCE(pf.reduced_tax_amount,0) + COALESCE(pf.standard_taxamount,0) + COALESCE(pf.tax_adjustment,0) END ) OVER () AS total_tax, SUM(COALESCE(pf.payment_amount,0)) OVER () AS total_payments, SUM(COALESCE(pf.current_balance,0)) OVER () AS total_current_balance
FROM payables_file AS pf LEFT JOIN supplier AS s ON s.id = pf.supplier_id WHERE pf.year_month = ':1' AND ( (:2 = 0 AND :3 = 0) OR (pf.supplier_id BETWEEN :2 AND :3) ) ORDER BY pf.supplier_id;
